inline const BakedFont& getBakedFont(FontFace face) noexcept {
    switch (face) {
        case FontFace::InterRegular12:  return kFont_InterRegular12;
        case FontFace::InterSemiBold13: return kFont_InterSemiBold13;
        case FontFace::InterBold16:     return kFont_InterBold16;
        case FontFace::InterBold22:     return kFont_InterBold22;
        case FontFace::MonoRegular12:   return kFont_MonoRegular12;
        case FontFace::MonoBold12:      return kFont_MonoBold12;
    }
    return kFont_InterRegular12;
}

